+ 'var layout={title:{text:"Split-Apply-Combine: Group Means by Field",font:{color:"#ebe6dc",size:14}},paper_bgcolor:"rgba(0,0,0,0)",plot_bgcolor:"rgba(0,0,0,0)",font:{color:"#ebe6dc"},xaxis:{title:"Student",gridcolor:"rgba(255,255,255,0.06)"},yaxis:{title:"Score",gridcolor:"rgba(255,255,255,0.06)",range:[60,100]},shapes:shapes,annotations:annots,margin:{t:50,r:30,b:60,l:50}};'
